#### SPSC 环形队列
保留一个空槽区分满和空；容量为 Capacity，数组实际 Capacity+1。写方独占 head，读方独占 tail，数据槽的复用由索引的 release/acquire 保证。64 字节对齐用于减少常见机器上的伪共享，不声称所有 CPU 缓存行都是 64 字节。
<!-- interview:SPSC -->
```cpp
template <std::size_t Capacity> class SpscQueue {
    static_assert(Capacity > 0 && Capacity < std::numeric_limits<std::size_t>::max() / sizeof(int));
    static_assert(std::atomic<std::size_t>::is_always_lock_free);
    std::array<int, Capacity + 1> buffer{};
    alignas(64) std::atomic<std::size_t> head{0}; // 仅生产者写，指向下次写入。
    alignas(64) std::atomic<std::size_t> tail{0}; // 仅消费者写，指向下次读取。
  public:
    bool tryPush(int value) noexcept {
        const auto at = head.load(std::memory_order_relaxed);
        const auto next = (at + 1) % (Capacity + 1);
        if (next == tail.load(std::memory_order_acquire))
            return false;
        buffer[at] = value;
        head.store(next, std::memory_order_release);
        return true;
    }
    bool tryPop(int &value) noexcept {
        const auto at = tail.load(std::memory_order_relaxed);
        if (at == head.load(std::memory_order_acquire))
            return false;
        value = buffer[at];
        tail.store((at + 1) % (Capacity + 1), std::memory_order_release);
        return true;
    }
};
```

